'use strict';
(function(root){
let current=null;const E_distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function scene(D,skill,round=0){const p=D.characters[skill.heroId],ops=skill.actions.map(a=>a.op),ranged=skill.range>200&&!ops.includes('dash'),delivery=skill.target==='self'?'self':ops.includes('dash')?'charge':ranged?'ranged':'melee',multi=skill.target==='area'||skill.actions.some(a=>['blast','beam','cone','zone','mine','spread','barrage'].includes(a.op)||['pet','summon'].includes(a.op)&&a.count>1),count=multi?6:1,hero={x:ranged||delivery==='charge'?125:225,y:225},center={x:hero.x+(ranged||delivery==='charge'?295:90),y:225};
const pool=D.regions.slice(0,6).flatMap(r=>r.monsters.slice(0,3).map(m=>({...m,boss:false})).concat(r.bosses.map(m=>({...m,boss:true})))),offsets=[[0,0],[60,-45],[75,45],[-50,-40],[-45,45],[120,0]],start=(round*5+skill.heroId*3+skill.cell+skill.slot)%pool.length,enemies=Array.from({length:count},(_,i)=>{const model=pool[(start+i*7)%pool.length],o=offsets[i];return {model,x:center.x+o[0],y:center.y+o[1],height:model.boss?72:56};});
return {D,skill,hero,enemies,delivery,multi,count,label:(delivery==='self'?'자기 강화':delivery==='charge'?'접근·기동 기술':delivery==='ranged'?'원거리 기술':'근접 기술')+(multi?' · 다수 대상':''),round};}
function simulation(sc){const E=root.RPG_ENGINE||(typeof require!=='undefined'?require('./rpg-engine.js'):null);if(!E)return null;const g=new E.Game(sc.D);g.select(sc.skill.heroId);g.h.cell=sc.skill.cell;g.h.level=99;g.h.autoPotion=false;g.autoSkill=false;g.start();g.c.zone=4;g.c.x=sc.hero.x;g.c.y=sc.hero.y;g.c.hp=g.stats().maxHP*.6;g.c.mp=100;g.c.skillTimer=0;g.c.extraTimers=[0,0,0];g.c.enemies=sc.enemies.map((e,i)=>({...g.enemy(e.model,false,e.x,e.y),id:i+100,hp:1e7,maxHP:1e7,attack:0}));g.uid=200;g.initSkills();g.c.meters={...g.c.meters,combo:6,revenge:g.stats().attack*4,blood:3,soul:3,heat:60,spellbullet:3,ammo:12,chord:2};g.c.songPower=5;g.c.wardBuff=5;
const t=g.c.enemies[0],ctx={combat:g.c,d:sc.skill,target:t,point:{x:t.x,y:t.y},origin:sc.hero,attack:g.stats().attack,multi:1,event:{}};
for(const a of sc.skill.actions){if(a.op==='fusion')g.newPet({appearance:a.appearance==='chimera'?'homunculus':'spirit',count:3,power:.4,duration:20},ctx);if(a.op==='split')g.newPet({appearance:'fusion',count:1,power:1,duration:20},ctx);if(['command','pet-buff','grow','repair','king-element'].includes(a.op)&&!g.c.devices.length)g.newPet({appearance:a.op==='grow'?'homunculus':a.op==='king-element'?'king':sc.skill.heroId===8?'beast':'spirit',count:2,power:.6,duration:20},ctx);if(['consume','spread','reaction'].includes(a.op))g.addStatus(t,a.type||'acid',{power:.2,stacks:3,duration:10});if(a.op==='detonate'&&a.type==='mine')g.performSkillAction({op:'mine',count:4,power:1,radius:95,arm:99},ctx);if(a.op==='detonate'&&a.type==='rune'||a.op==='link-runes')for(let i=0;i<3;i++)g.c.techZones.push({x:t.x+(i-1)*60,y:t.y+(i%2)*35,type:'rune',radius:55,life:20,timer:99,power:.1,ctx});if(a.op==='swap')g.c.decoys=[{x:t.x-65,y:t.y,life:15,hits:10}];if(a.op==='corpses')g.c.corpses=[{x:t.x,y:t.y},{x:t.x+20,y:t.y}];}
g.events=[];return {g,time:0,cast:false};}
function pose(sc,age){if(!sc.skill.mechanicsVersion)return {hero:sc.hero,enemies:sc.enemies};const key=sc.skill.id+':'+sc.round;if(!current||current.key!==key||age<current.age){current={key,age:0,...simulation(sc)};}if(!current.g)return {hero:sc.hero,enemies:sc.enemies};const {g}=current;
if(age>=.35&&!current.cast){if(!sc.skill.basic)g.castSkill(sc.skill.slot,true);current.cast=true;}
let elapsed=Math.max(0,age-current.age);while(elapsed>0){const dt=Math.min(.04,elapsed);g.time+=dt;if(current.cast){g.tickSkills(dt);g.tickTechniques(dt);if(sc.skill.basic){const target=g.c.enemies[0],range=Math.max(85,g.stats().range);g.c.atkTimer=Math.max(0,g.c.atkTimer-dt);const distance=target?E_distance(g.c,target):0;if(target&&distance>range){g.c.x+=(target.x-g.c.x)/distance*dt*110;g.c.y+=(target.y-g.c.y)/distance*dt*110;}if(target&&distance<=range+5&&g.c.atkTimer<=0)g.attack(target);}for(const enemy of g.c.enemies){enemy.root=Math.max(0,(enemy.root||0)-dt);const distance=E_distance(g.c,enemy);if(!enemy.root&&!sc.skill.basic&&sc.delivery==='melee'&&distance>38){enemy.x+=(g.c.x-enemy.x)/distance*dt*25;enemy.y+=(g.c.y-enemy.y)/distance*dt*25;}if(distance<45&&g.time-(enemy.lastAttack??-99)>1.1){g.takeDamage(1,enemy);enemy.lastAttack=g.time;}}if(g.c.formTime>0){g.c.formTime=Math.max(0,g.c.formTime-dt);}if(g.c.formTime>0&&g.time-(g.c.lastBasic??-99)>.7){const target=g.c.enemies[0];if(target){g.c.x=Math.max(80,target.x-35);g.c.y=target.y;g.attack(target);}}}elapsed-=dt;}
current.age=age;return {hero:{x:g.c.x,y:g.c.y},enemies:sc.enemies.map((e,i)=>({...e,x:g.c.enemies[i]?.x??e.x,y:g.c.enemies[i]?.y??e.y})),sim:g,delivery:sc.delivery,round:sc.round,count:sc.count};}
function drawObjects(pc,D,skill,sc,age,drawSprite){if(!sc.sim)return;const g=sc.sim,c=g.c;for(const z of c.techZones)root.RPG_SKILL_FX?.drawZone(pc,z,age);if(c.smokeTime>0)root.RPG_SKILL_FX?.smoke(pc,c.x,c.y,age,95,.8);for(const m of c.mines)root.RPG_SKILL_FX?.drawMine(pc,m,age);for(const d of c.decoys)root.RPG_ENTITIES?.draw(pc,'decoy',d.x,d.y,age,{height:55});for(const d of c.devices){if(d.kind==='turret')root.RPG_ENTITIES?.draw(pc,'turret',d.x,d.y,age,{height:50,guard:d.guard,firing:d.timer<.18});else if(d.skin)root.RPG_ENTITIES?.draw(pc,d.skin,d.x,d.y,age,{height:d.large?82:48,firing:d.timer>1});else drawSprite(pc,d.sheet,d.cell,d.x,d.y,d.large?82:45,d.facing,1,root.RPG_MOTION?.pose(age,true,d.timer>1?age-(1.3-d.timer):-99,-99,d.appearance==='beast'?'fighter':'sword'));}for(const p of c.friendly)root.RPG_SKILL_FX?.projectile(pc,skill.heroId===8?'arrow':skill.heroId===9?'bullet':'magic',p.x,p.y,Math.atan2(p.vy||0,p.vx||1),age,38);if(c.dragonTime>0)root.RPG_ENTITIES?.draw(pc,'dragon',c.x,c.y,age,{height:85,firing:age%1<.3});}
function basic(D,heroId,cell,round=0){const p=D.characters[heroId],ranged=['mage','archer','gunner','summoner'].includes(p.family);return scene(D,{id:'basic-'+heroId+'-'+cell,heroId,cell,slot:0,name:'기본공격',target:'single',range:ranged?300:100,mechanicsVersion:3,actions:[],basic:true},round);}
const api={scene,pose,drawObjects,basic};if(typeof module!=='undefined')module.exports=api;root.RPG_PREVIEW=api;
})(typeof window!=='undefined'?window:globalThis);
